<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,shallowRef,watch} from 'vue'
import {request} from './api'
import {fetchClasses,type RosterClass} from './records'
import {type FormalAssignment,cropFile,artifact,type CropRun} from './formalUpload'
import {loadLayout,saveLayout,referenceUrl,normalizedPoint,dragBox,validBox,type LayoutContext,type LayoutRegion,type BBox} from './layoutEditor'
import type {ExamContext} from './navigation'
const props=defineProps<{initialContext?:ExamContext}>()
const assignments=ref<FormalAssignment[]>([]),classes=ref<RosterClass[]>([]),exams=ref<{exam_id:string}[]>([]),assignment=ref(''),className=ref(''),exam=ref(''),context=shallowRef<LayoutContext>(),regions=ref<LayoutRegion[]>([]),page=ref(0),question=ref(''),box=ref<BBox>({x1:0,y1:0,x2:0,y2:0}),loaded=ref(false),confirmed=ref(false),clearConfirmed=ref(false),busy=ref(false),error=ref(''),message=ref(''),uncertain=ref(false),testFile=shallowRef<File>(),testMode=ref('single_page'),testResult=shallowRef<CropRun>()
let alive=true,revision=0,start:{x:number;y:number}|null=null
const shown=computed(()=>regions.value.filter(r=>r.page_number===page.value)),pending=computed(()=>validBox(box.value)&&JSON.stringify(regions.value.find(r=>r.question_id===question.value)?.bbox)!==JSON.stringify(box.value))
function reset(){revision++;context.value=undefined;regions.value=[];testResult.value=undefined;confirmed.value=false;clearConfirmed.value=false;loaded.value=false;uncertain.value=false;error.value='';message.value='';box.value={x1:0,y1:0,x2:0,y2:0}}
async function chooseAssignment(){reset();exam.value='';exams.value=[];if(!assignment.value)return;const n=revision;busy.value=true;try{const a=assignments.value.find(a=>a.id===assignment.value);const list=className.value?(await request<{exams:{exam_id:string}[]}>('/api/class-exams?class_name='+encodeURIComponent(className.value)+'&assignment_id='+assignment.value)).exams:(a?.layout_exams?.length?a.layout_exams:a?.exam_id?[{exam_id:a.exam_id}]:[]);if(!alive||n!==revision)return;exams.value=list;if(list.length===1)exam.value=list[0]!.exam_id}catch(e){if(alive&&n===revision)error.value=(e as Error).message}finally{if(alive&&n===revision)busy.value=false}}
async function read(){reset();if(!exam.value)return;const n=revision;busy.value=true;try{const c=await loadLayout(exam.value);if(!alive||n!==revision)return;if(c.assignment_id!==assignment.value)throw new Error('考试与作业不一致');context.value=c;regions.value=structuredClone(c.layout_profile?.regions||[]);page.value=c.references[0]?.page_number||0;question.value=c.subjective_question_ids[0]||'';selectBox()}catch(e){if(alive&&n===revision)error.value=(e as Error).message}finally{if(alive&&n===revision)busy.value=false}}
function selectBox(){const r=regions.value.find(r=>r.question_id===question.value);box.value=r?{...r.bbox}:{x1:0,y1:0,x2:0,y2:0};if(r&&r.page_number!==page.value){page.value=r.page_number;loaded.value=false}confirmed.value=false}
function begin(e:PointerEvent){if(!loaded.value||busy.value||uncertain.value||!question.value)return;e.preventDefault();(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);start=normalizedPoint(e.clientX,e.clientY,(e.currentTarget as HTMLElement).getBoundingClientRect());confirmed.value=false}
function end(e:PointerEvent){if(!start)return;const b=normalizedPoint(e.clientX,e.clientY,(e.currentTarget as HTMLElement).getBoundingClientRect());box.value=dragBox(start,b);start=null}
function apply(){if(!context.value||!validBox(box.value)||!question.value)return;regions.value=[...regions.value.filter(r=>r.question_id!==question.value),{question_id:question.value,page_number:page.value,region_type:'subjective_answer',bbox:{...box.value}}];confirmed.value=false;testResult.value=undefined}
function remove(){regions.value=regions.value.filter(r=>r.question_id!==question.value);box.value={x1:0,y1:0,x2:0,y2:0};confirmed.value=false;testResult.value=undefined}
async function save(clear=false){if(busy.value||uncertain.value||!context.value||(!clear&&(!confirmed.value||pending.value))||(clear&&!clearConfirmed.value))return;const n=revision;busy.value=true;try{await saveLayout(context.value,clear?[]:JSON.parse(JSON.stringify(regions.value)),clear?clearConfirmed.value:confirmed.value);if(!alive||n!==revision)return;await read();if(alive)message.value=clear?'所有答题区已清空，正式评分将被阻断。':'答题区已保存。正式上传仍需通过配准、裁切验收与隐私确认。'}catch{if(alive&&n===revision){uncertain.value=true;error.value='保存结果未能确认，请重新读取服务器布局；不会自动重试。'}}finally{if(alive)busy.value=false}}
async function test(){if(!testFile.value||!context.value||busy.value||uncertain.value)return;const n=revision;busy.value=true;error.value='';testResult.value=undefined;try{const r=await cropFile(testFile.value,exam.value,testMode.value);if(alive&&n===revision)testResult.value=r}catch(e){if(alive&&n===revision)error.value=(e as Error).message}finally{if(alive&&n===revision)busy.value=false}}
watch(page,()=>{loaded.value=false;confirmed.value=false})
onMounted(async()=>{const n=revision;busy.value=true;try{const [a,c]=await Promise.all([request<{assignments:FormalAssignment[]}>('/api/assignments'),fetchClasses()]);if(alive&&n===revision){assignments.value=a.assignments;classes.value=c;if(props.initialContext?.assignmentId){assignment.value=props.initialContext.assignmentId;className.value=props.initialContext.className||'';await chooseAssignment();if(props.initialContext.examId){exam.value=props.initialContext.examId;if(!exams.value.some(e=>e.exam_id===exam.value))exams.value=[...exams.value,{exam_id:exam.value}];await read()}}}}catch(e){if(alive)error.value=(e as Error).message}finally{if(alive)busy.value=false}})
onUnmounted(()=>{alive=false;revision++;context.value=undefined;testFile.value=undefined;testResult.value=undefined})
</script>
<template><section><h2>正式答题区布局编辑</h2><p>只在干净PDF参考页上设置共享答题区，不按学生答案逐卷调框，不修改评分细则。保存后仍需重新走正式裁切验收。</p><p v-if="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p>
 <fieldset :disabled="busy"><legend>选择布局来源</legend><label v-if="!initialContext?.assignmentId" for="layout-assignment">布局所属作业</label><select v-show="!initialContext?.assignmentId" id="layout-assignment" v-model="assignment" @change="chooseAssignment"><option value="">请选择</option><option v-for="a in assignments" :key="a.id" :value="a.id">{{ a.name }}</option></select><label v-if="!initialContext?.examId" for="layout-class">布局班级</label><select v-show="!initialContext?.examId" id="layout-class" v-model="className" @change="chooseAssignment"><option value="">不关联班级</option><option v-for="c in classes" :key="c.class_name">{{ c.class_name }}</option></select><label v-if="!initialContext?.examId" for="layout-exam">布局考试</label><select v-show="!initialContext?.examId" id="layout-exam" v-model="exam" @change="reset"><option value="">请选择</option><option v-for="e in exams" :key="e.exam_id">{{ e.exam_id }}</option></select><button @click="read" :disabled="!exam">读取服务器布局</button></fieldset>
 <template v-if="context"><p>PDF SHA256：{{ context.source_pdf_sha256 }}；服务端状态{{ context.status }}，已设置{{ context.configured_count }} / {{ context.required_count }}。</p><p v-if="!context.has_pdf_reference||context.pdf_hash_mismatch" role="alert">PDF来源缺失或hash不一致，不能保存布局。</p>
  <fieldset :disabled="busy||uncertain"><legend>参考页与答题框</legend><label for="layout-page">参考页</label><select id="layout-page" v-model.number="page"><option v-for="p in context.references" :key="p.page_number" :value="p.page_number">第{{ p.page_number }}页</option></select><label for="layout-question">答题区对应小题</label><select id="layout-question" v-model="question" @change="selectBox"><option v-for="q in context.subjective_question_ids" :key="q">{{ q }}</option></select>
   <div v-if="page" class="coordinate-editor" aria-label="布局参考框选区" @pointerdown="begin" @pointerup="end" @pointercancel="start=null"><img :key="exam+':'+page" :src="referenceUrl(exam,page)" :alt="'布局参考第'+page+'页'" @load="loaded=true" @error="loaded=false;error='参考页无法读取，请核对PDF来源。'"><svg viewBox="0 0 1 1" preserveAspectRatio="none" aria-hidden="true"><rect v-for="r in shown" :key="r.question_id" :x="r.bbox.x1" :y="r.bbox.y1" :width="r.bbox.x2-r.bbox.x1" :height="r.bbox.y2-r.bbox.y1" fill="none" stroke="#1763ad" stroke-width=".003"/><rect v-if="validBox(box)" :x="box.x1" :y="box.y1" :width="box.x2-box.x1" :height="box.y2-box.y1" fill="#00aa4422" stroke="#00842d" stroke-width=".004"/></svg></div>
   <p>在参考页拖框，或输入0—1归一化坐标，然后先“应用”再保存。只框学生作答区，避开材料正文和身份区域。</p><div class="coordinate-numbers"><label v-for="k in (['x1','y1','x2','y2'] as const)" :key="k">布局{{ k }}<input type="number" min="0" max="1" step="0.001" v-model.number="box[k]" @input="confirmed=false"></label></div><button @click="apply" :disabled="!validBox(box)||!loaded">应用此答题区到布局草稿</button> <button @click="remove">删除所选题答题区草稿</button><p v-if="pending" role="alert">坐标修改尚未应用，请先应用到草稿。</p><p>布局草稿：{{ regions.map(r=>r.question_id+'（第'+r.page_number+'页）').join('、')||'空' }}。未覆盖的题目不会通过正式上传门禁。</p>
   <label class="check"><input type="checkbox" v-model="confirmed">我已核对共享布局的题号、页码、手写完整性与材料边界</label><button @click="save()" :disabled="!confirmed||pending||!context.has_pdf_reference||context.pdf_hash_mismatch">保存正式答题区布局</button>
   <details><summary>清空全部布局</summary><label class="check"><input type="checkbox" v-model="clearConfirmed">确认清空本场所有答题区，正式评分将被阻断</label><button @click="save(true)" :disabled="!clearConfirmed">确认清空布局</button></details>
  </fieldset>
  <fieldset :disabled="busy||uncertain"><legend>用已保存布局试裁切（不调用模型）</legend><label>布局试裁切照片<input type="file" accept=".png,.jpg,.jpeg" @change="testFile=($event.target as HTMLInputElement).files?.[0];testResult=undefined"></label><label for="layout-test-mode">试裁切照片版式</label><select id="layout-test-mode" v-model="testMode"><option value="single_page">单页</option><option value="double_spread">双页展开</option></select><button @click="test" :disabled="!testFile">执行本地配准与试裁切</button><p v-if="testResult">试裁切结果：{{ testResult.status }}。这里只查看结果，不签发上传凭据或调用模型。</p><figure v-for="crop in testResult?.crops" :key="crop.question_id"><img class="upload-preview" :src="artifact(testResult!.alignment_run_id,crop.padding_validation_file_name||crop.file_name)" :alt="'试裁切'+crop.question_id"><figcaption>{{ crop.question_id }}</figcaption></figure></fieldset>
 </template></section></template>
